import pytest


def fact(n: int) -> int:
    """Return n! (the factorial of n) for n >= 0.

    fact(0) == 1. Raises ValueError when n is negative.
    """
    if n < 0:
        raise ValueError("fact() is undefined for negative numbers")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_one() -> None:
    assert fact(1) == 1


def test_fact_small() -> None:
    assert fact(5) == 120


def test_fact_larger() -> None:
    assert fact(10) == 3628800


def test_fact_negative_raises() -> None:
    with pytest.raises(ValueError):
        fact(-1)
